-- Supabase becomes the authoritative store for published editorial content.
-- Snapshot read from the public Sanity production dataset on 2026-10-12; drafts were excluded.
begin;

do $$
begin
  if to_regclass('public.managed_content_entries') is not null
    or to_regclass('public.admin_audit_log') is not null then
    raise exception 'managed editorial tables already exist; verify Production before applying this migration';
  end if;
end;
$$;

create table public.managed_content_entries (
  id uuid primary key default gen_random_uuid(),
  content_type text not null check (content_type in ('character', 'book', 'adventure', 'video', 'song', 'location', 'trailWaypoint', 'narrativeMilestone', 'mentionedCuriosity', 'wallpaper', 'seasonalEvent', 'letter', 'universeRoadmapItem', 'collaboration', 'siteSettings')),
  content_id text not null check (length(content_id) between 1 and 120),
  slug text check (slug is null or length(slug) between 1 and 120),
  payload jsonb not null check (jsonb_typeof(payload) = 'object'),
  sort_order integer not null default 0,
  is_published boolean not null default true,
  is_deleted boolean not null default false,
  created_by uuid references auth.users(id) on delete set null,
  updated_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (content_type, content_id)
);

create index managed_content_entries_public_order_idx
  on public.managed_content_entries (content_type, is_published, sort_order, content_id)
  where not is_deleted;
create unique index managed_content_entries_active_slug_idx
  on public.managed_content_entries (content_type, slug)
  where slug is not null and not is_deleted;

create table public.admin_audit_log (
  id uuid primary key default gen_random_uuid(),
  actor_user_id uuid references auth.users(id) on delete set null,
  action text not null check (action in ('create', 'update', 'publish', 'unpublish', 'delete', 'restore')),
  resource_type text not null,
  resource_id text not null,
  created_at timestamptz not null default now()
);
create index if not exists admin_audit_log_created_at_idx on public.admin_audit_log (created_at desc);

create or replace function public.audit_managed_content_entry()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  entry public.managed_content_entries;
  event_action text;
begin
  if tg_op = 'DELETE' then
    entry := old;
    event_action := 'delete';
  else
    entry := new;
    if tg_op = 'INSERT' then
      event_action := 'create';
    elsif old.is_deleted is distinct from new.is_deleted then
      event_action := case when new.is_deleted then 'delete' else 'restore' end;
    elsif old.is_published is distinct from new.is_published then
      event_action := case when new.is_published then 'publish' else 'unpublish' end;
    else
      event_action := 'update';
    end if;
  end if;
  if entry.updated_by is not null then
    insert into public.admin_audit_log (actor_user_id, action, resource_type, resource_id)
    values (entry.updated_by, event_action, entry.content_type, entry.content_id);
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;
drop trigger if exists managed_content_entries_audit_trigger on public.managed_content_entries;
create trigger managed_content_entries_audit_trigger
  after insert or update or delete on public.managed_content_entries
  for each row execute function public.audit_managed_content_entry();

alter table public.managed_content_entries enable row level security;
alter table public.admin_audit_log enable row level security;
revoke all on public.managed_content_entries from public, anon, authenticated;
revoke all on public.admin_audit_log from public, anon, authenticated;
grant all on public.managed_content_entries to service_role;
grant all on public.admin_audit_log to service_role;
revoke all on function public.audit_managed_content_entry() from public, anon, authenticated;

create or replace function public.set_admin_profile_role(
  p_actor_user_id uuid,
  p_target_user_id uuid,
  p_role text,
  p_display_name text
) returns void
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $$
declare
  existing_profile_role text;
  audit_action text;
begin
  perform pg_advisory_xact_lock(hashtext('curileta-admin-owner-count')::bigint);
  if not exists (
    select 1 from public.admin_profiles
    where user_id = p_actor_user_id and role = 'owner'
  ) then
    raise exception 'Solo la persona propietaria puede gestionar el equipo';
  end if;
  if p_role is not null and p_role not in ('owner', 'admin', 'editor', 'analyst') then
    raise exception 'El rol indicado no es válido';
  end if;
  if p_display_name is null or length(btrim(p_display_name)) > 120 then
    raise exception 'El nombre debe tener como máximo 120 caracteres';
  end if;
  if not exists (select 1 from auth.users where id = p_target_user_id) then
    raise exception 'La cuenta no existe en Supabase Auth';
  end if;

  select role into existing_profile_role from public.admin_profiles
    where user_id = p_target_user_id for update;
  if existing_profile_role = 'owner' and p_role is distinct from 'owner'
    and (select count(*) from public.admin_profiles where role = 'owner') <= 1 then
    raise exception 'Debe permanecer al menos una persona propietaria';
  end if;

  if p_role is null then
    if existing_profile_role is null then
      raise exception 'La cuenta no tiene acceso al panel';
    end if;
    delete from public.admin_profiles where user_id = p_target_user_id;
    audit_action := 'delete';
  else
    insert into public.admin_profiles (user_id, display_name, role)
      values (p_target_user_id, btrim(p_display_name), p_role)
      on conflict (user_id) do update
        set display_name = excluded.display_name,
            role = excluded.role,
            updated_at = now();
    audit_action := case when existing_profile_role is null then 'create' else 'update' end;
  end if;

  insert into public.admin_audit_log (actor_user_id, action, resource_type, resource_id)
    values (p_actor_user_id, audit_action, 'admin_profile', p_target_user_id::text);
end;
$$;
revoke all on function public.set_admin_profile_role(uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.set_admin_profile_role(uuid, uuid, text, text) to service_role;

